// Duas janelas de 48h (+1 dia de folga no fim, já que a data final da API é só 'yyyy-MM-dd'):
//  - abertura: pega atendimentos novos
//  - encerramento: pega os que FECHARAM agora, mesmo se abriram antes da janela (atualiza EA -> F)
const N = $('Config').first().json.paginas;
const hoje = $now.setZone('America/Fortaleza');
const ini = hoje.minus({ days: 2 }).toFormat('yyyy-MM-dd');
const fim = hoje.plus({ days: 1 }).toFormat('yyyy-MM-dd');
const janelas = {
  abertura: { dataInicialAbertura: ini, dataFinalAbertura: fim },
  encerramento: { dataInicialEncerramento: ini, dataFinalEncerramento: fim },
};
const out = [];
for (const [janela, filter] of Object.entries(janelas)) {
  for (let i = 0; i < N; i++) out.push({ json: { janela, filter, skip: i * 1000 } });
}
return out;

// Normaliza o atendimento cru da Opa Suite para o schema do banco noc.
// LGPD: id_cliente, id_user, canal_cliente, tags, observações e mensagens NUNCA são lidos.

const idOf = (v) => (v && typeof v === 'object') ? (v._id || v.id || v.idMotivo || null) : (v || null);

// Horário comercial PROVISÓRIO (seg-sex 8h-18h, sáb 8h-12h), no fuso de Fortaleza (UTC-3, sem horário de verão).
// Evolução: ler os períodos reais pelo endpoint /periodo da Opa Suite.
function foraDoHorario(iso) {
  const t = new Date(iso);
  if (isNaN(t)) return null;
  const local = new Date(t.getTime() - 3 * 3600 * 1000);
  const dia = local.getUTCDay();   // 0 = domingo
  const hora = local.getUTCHours();
  if (dia === 0) return true;
  if (dia === 6) return !(hora >= 8 && hora < 12);
  return !(hora >= 8 && hora < 18);
}

// Nota da pesquisa de satisfação do CLIENTE (likert, 1 a 5). A nota da IA não entra aqui de propósito.
// Formato real (conferido em 27/11): evaluations = [{ metric: 'likert', likert: { rating, topic }, date }, ...]
// Se houver mais de uma, prefere topic 'all' e, entre elas, a mais recente.
function extrairRating(item) {
  let cands = [];
  if (Array.isArray(item.evaluations)) {
    cands = item.evaluations
      .filter((e) => e && (e.metric === 'likert' || e.likert) && e.likert && e.likert.rating != null)
      .map((e) => ({ r: Number(e.likert.rating), all: e.likert.topic === 'all', t: Date.parse(e.date) || 0 }));
  } else if (item.evaluations && item.evaluations.likert && item.evaluations.likert.rating != null) {
    cands = [{ r: Number(item.evaluations.likert.rating), all: true, t: 0 }];
  }
  cands = cands.filter((c) => !isNaN(c.r));
  if (!cands.length) return null;
  cands.sort((a, b) => (b.all - a.all) || (b.t - a.t));
  return cands[0].r;
}

// Motivo: formato novo (motivos[].idMotivo) ou antigo (id_motivo_atendimento). Usa o primeiro.
function extrairMotivo(item) {
  if (Array.isArray(item.motivos) && item.motivos.length) {
    const m = item.motivos[0];
    return idOf(m && typeof m === 'object' && 'idMotivo' in m ? m.idMotivo : m);
  }
  return idOf(item.id_motivo_atendimento);
}

// Deduplica por _id (o mesmo atendimento pode vir na janela de abertura e na de encerramento).
const porId = new Map();
// Lê direto as respostas da API (uma por página) — sem nó intermediário guardando os registros brutos.
for (const resp of $input.all()) {
  for (const item of ((resp.json && resp.json.data) || [])) {
  if (!item || !item._id) continue;
  porId.set(item._id, {
    id: item._id,
    protocolo: item.protocolo || null,
    status: item.status || null,
    canal_tipo: item.canal || null,
    canal_id: idOf(item.canal_id),
    setor_id: idOf(item.setor),
    atendente_id: idOf(item.id_atendente),
    motivo_id: extrairMotivo(item),
    data_abertura: item.date || null,
    data_encerramento: item.fim || null,
    fora_horario: item.date ? foraDoHorario(item.date) : null,
    rating: extrairRating(item),
  });
  }
}
return [...porId.values()].map((json) => ({ json }));

const paginas = $('Gerar páginas').all().map((i) => i.json);
const respostas = $('Buscar atendimentos').all();
const ultima = {};
paginas.forEach((p, i) => { ultima[p.janela] = i; });
const cheias = Object.entries(ultima)
  .filter(([, i]) => (((respostas[i] || {}).json || {}).data || []).length >= 1000)
  .map(([k]) => k);
return [{ json: {
  fluxo: 'opa_sync_atendimentos',
  registros: $('Separar e normalizar (LGPD)').all().length,
  status: cheias.length ? 'verificar_paginas' : 'ok',
  detalhe: cheias.length ? 'Última página cheia em: ' + cheias.join(', ') + ' — aumente as páginas no Config' : null,
} }];
